-- -------------------------------------------------------------
-- Table structure for table `broadcast_log_recipients`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `broadcast_log_recipients`;
CREATE TABLE `broadcast_log_recipients` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `broadcast_log_id` varchar(100) NOT NULL,
  `recipient_id` varchar(100) DEFAULT NULL,
  `recipient_name` varchar(150) DEFAULT NULL,
  `phone` varchar(30) DEFAULT NULL,
  `formatted_phone` varchar(40) DEFAULT NULL,
  `source` varchar(50) DEFAULT NULL,
  `status` varchar(50) DEFAULT NULL,
  `whatsapp_url` text,
  `web_whatsapp_url` text,
  PRIMARY KEY (`id`),
  KEY `fk_broadcast_recipient_log` (`broadcast_log_id`),
  KEY `idx_broadcast_recipient_phone` (`phone`),
  KEY `idx_broadcast_recipient_source` (`source`),
  CONSTRAINT `fk_broadcast_recipient_log` FOREIGN KEY (`broadcast_log_id`) REFERENCES `broadcast_logs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- -------------------------------------------------------------
-- Table structure for table `broadcast_logs`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `broadcast_logs`;
CREATE TABLE `broadcast_logs` (
  `id` varchar(100) NOT NULL,
  `offer_id` varchar(100) DEFAULT NULL,
  `offer_code` varchar(80) DEFAULT NULL,
  `offer_title` varchar(250) DEFAULT NULL,
  `discount_percent` decimal(5,2) DEFAULT NULL,
  `discount_amount` decimal(12,2) DEFAULT NULL,
  `dispatched_at` varchar(50) DEFAULT NULL,
  `total_recipients` int NOT NULL DEFAULT '0',
  `breakdown` json DEFAULT NULL,
  `status` varchar(50) DEFAULT NULL,
  `message_text` longtext,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_broadcast_offer` (`offer_id`),
  KEY `idx_broadcast_dispatched` (`dispatched_at`),
  KEY `idx_broadcast_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

